/**
 * CSP policy parity guard (CSP Phase 2B).
 *
 * FluentStellar's production CSP is declared once, in src/security/csp.ts,
 * but has to reach the browser through two independent delivery surfaces
 * that can never share a single HTTP response:
 *   - public/_headers (Cloudflare Static Assets — generated by
 *     scripts/security/generate-headers-file.mjs, never hand-edited)
 *   - workers/word-ssr/src/index.full.ts (the Worker's own response
 *     headers, via withDataVersionHeaders + the /records/* 404 guard)
 *
 * This test proves both surfaces stay semantically identical to the
 * canonical policy — by parsing directive/value sets (not comparing raw
 * strings, since _headers has its own file syntax around the value) — and
 * fails if either one drifts: public/_headers goes stale relative to a
 * csp.ts edit, or index.full.ts stops actually using the shared constant.
 *
 * Run: node scripts/tests/security/test-csp-policy-parity.mjs
 * No build required — reads repo source files directly.
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { compileTsToCommonJs, ROOT_DIR } from "../../lib/compileTs.mjs";

let passed = 0;
let failed = 0;

function test(name, fn) {
  try {
    fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`       ${err.message}`);
    failed++;
  }
}

function readFile(relPath) {
  return fs.readFileSync(path.join(ROOT_DIR, relPath), "utf8");
}

function mapsEqual(a, b) {
  if (a.size !== b.size) return false;
  for (const [key, values] of a) {
    const otherValues = b.get(key);
    if (!otherValues) return false;
    if (values.size !== otherValues.size) return false;
    for (const value of values) {
      if (!otherValues.has(value)) return false;
    }
  }
  return true;
}

function describeMap(map) {
  return [...map.entries()]
    .map(([directive, values]) => `${directive} ${[...values].sort().join(" ")}`)
    .sort()
    .join("; ");
}

// Extracts the header value from a single `_headers`-format rule block:
//   /*
//     Header-Name: value
function extractHeadersFileValue(headersFileContent, headerName) {
  const re = new RegExp(`^\\s*${headerName}:\\s*(.+)$`, "m");
  const match = headersFileContent.match(re);
  return match ? match[1].trim() : null;
}

async function main() {
  const compiled = compileTsToCommonJs(".tmp-csp-policy-parity", [
    path.join(ROOT_DIR, "src", "security", "csp.ts"),
  ]);

  try {
    const csp = compiled.require("src/security/csp");
    const canonicalValue = csp.buildCspHeaderValue();
    const canonicalMap = csp.parseCspHeaderValue(canonicalValue);

    console.log("\n[1] Both surfaces declare a Content-Security-Policy-Report-Only, never an enforcing one");
    test("src/security/csp.ts's CSP_HEADER_NAME is the Report-Only variant", () => {
      assert.equal(csp.CSP_HEADER_NAME, "Content-Security-Policy-Report-Only");
    });

    const headersFile = readFile("public/_headers");
    test("public/_headers declares Content-Security-Policy-Report-Only", () => {
      assert.ok(
        extractHeadersFileValue(headersFile, "Content-Security-Policy-Report-Only") !== null,
        "public/_headers is missing a Content-Security-Policy-Report-Only line",
      );
    });
    test("public/_headers does not also declare an enforcing Content-Security-Policy", () => {
      assert.equal(
        extractHeadersFileValue(headersFile, "Content-Security-Policy"),
        null,
        "public/_headers declares an enforcing Content-Security-Policy header — CSP Phase 2B is Report-Only only",
      );
    });

    const workerSource = readFile("workers/word-ssr/src/index.full.ts");
    test("index.full.ts imports CSP_HEADER_NAME/buildCspHeaderValue from src/security/csp", () => {
      assert.match(
        workerSource,
        /import\s*\{\s*CSP_HEADER_NAME\s*,\s*buildCspHeaderValue\s*\}\s*from\s*"\.\.\/\.\.\/\.\.\/src\/security\/csp"/,
      );
    });
    test("index.full.ts never hardcodes an enforcing \"Content-Security-Policy\" header name itself", () => {
      // The only allowed appearance of the substring "Content-Security-Policy"
      // in this file is as part of the imported CSP_HEADER_NAME identifier
      // itself (checked above) — never as a locally hardcoded string literal,
      // which would bypass csp.ts as the single source of truth.
      assert.ok(
        !/"Content-Security-Policy(?!-Report-Only)"/.test(workerSource),
        'index.full.ts hardcodes a "Content-Security-Policy" string literal instead of importing CSP_HEADER_NAME',
      );
    });
    test("index.full.ts's withDataVersionHeaders attaches the CSP header to every response it builds", () => {
      assert.match(workerSource, /\[CSP_HEADER_NAME\]:\s*CSP_HEADER_VALUE/);
    });
    test("index.full.ts's /records/* 404 guard (which bypasses withDataVersionHeaders) also carries the CSP header", () => {
      const recordsGuardMatch = workerSource.match(
        /url\.pathname\.startsWith\("\/records\/"\)\)\s*\{\s*return new Response\("Not Found",\s*\{[\s\S]*?\}\);\s*\}/,
      );
      assert.ok(recordsGuardMatch, "could not locate the /records/* 404 guard — has it moved or been rewritten?");
      assert.match(recordsGuardMatch[0], /\[CSP_HEADER_NAME\]:\s*CSP_HEADER_VALUE/);
    });

    console.log("\n[2] Directive semantics are identical across both surfaces");
    const headersFileValue = extractHeadersFileValue(headersFile, "Content-Security-Policy-Report-Only");
    const headersFileMap = csp.parseCspHeaderValue(headersFileValue ?? "");
    test("public/_headers's policy is byte-for-directive identical to src/security/csp.ts's canonical policy", () => {
      assert.ok(
        mapsEqual(headersFileMap, canonicalMap),
        `public/_headers is stale relative to src/security/csp.ts — regenerate with ` +
          `\`node scripts/security/generate-headers-file.mjs\`.\n` +
          `  _headers: ${describeMap(headersFileMap)}\n` +
          `  canonical: ${describeMap(canonicalMap)}`,
      );
    });
    test("index.full.ts's Worker policy is the same CSP_HEADER_VALUE constant (buildCspHeaderValue()) — no second, hand-written policy string", () => {
      // Guards against exactly the drift this test exists to catch: a second
      // CSP string hardcoded directly in the Worker instead of importing the
      // one canonical value. Only one call to buildCspHeaderValue() should
      // exist in this file, assigned once, referenced everywhere else.
      const calls = workerSource.match(/buildCspHeaderValue\(\)/g) ?? [];
      assert.equal(calls.length, 1, "buildCspHeaderValue() should be called exactly once (module scope), not duplicated or reimplemented");
      assert.ok(!/Content-Security-Policy-Report-Only["']?:\s*["'`]default-src/.test(workerSource), "found a second, hand-written CSP string in index.full.ts");
    });

    console.log("\n[3] No risky allowances in the canonical policy");
    const allSources = [...canonicalMap.values()].flatMap((set) => [...set]);
    test("no 'unsafe-inline'", () => assert.ok(!allSources.includes("'unsafe-inline'")));
    test("no 'unsafe-eval'", () => assert.ok(!allSources.includes("'unsafe-eval'")));
    test("no bare wildcard '*' source", () => assert.ok(!allSources.includes("*")));
    test("no broad 'https:' scheme source", () => assert.ok(!allSources.includes("https:")));
    test("no 'data:' source", () => assert.ok(!allSources.includes("data:")));
    test("no 'blob:' source", () => assert.ok(!allSources.includes("blob:")));
    test("no broad subdomain wildcard (e.g. '*.example.com') anywhere", () => {
      assert.ok(!allSources.some((source) => source.includes("*.")), `found a subdomain wildcard: ${allSources.filter((s) => s.includes("*."))}`);
    });
    test("no Cloudflare Web Analytics origin present (confirmed not enabled in production — see report)", () => {
      assert.ok(!allSources.some((source) => source.includes("cloudflareinsights.com")));
    });

    console.log("\n[4] Expected required origins are present exactly where needed");
    test("connect-src allows 'self' and the production Supabase origin, nothing else", () => {
      assert.deepEqual([...canonicalMap.get("connect-src")].sort(), ["'self'", csp.SUPABASE_ORIGIN].sort());
    });
    test("style-src allows the Google Fonts stylesheet origin", () => {
      assert.ok(canonicalMap.get("style-src").has("https://fonts.googleapis.com"));
    });
    test("font-src allows the Google Fonts file origin, not the stylesheet origin", () => {
      assert.ok(canonicalMap.get("font-src").has("https://fonts.gstatic.com"));
      assert.ok(!canonicalMap.get("font-src").has("https://fonts.googleapis.com"));
    });
    test("script-src does NOT allow the Google Fonts origin (fonts are style/font-src concerns only)", () => {
      assert.ok(![...canonicalMap.get("script-src")].some((s) => s.includes("fonts.g")));
    });
    test("frame-src and frame-ancestors are both 'none' (no embedding requirement found in the app)", () => {
      assert.deepEqual([...canonicalMap.get("frame-src")], ["'none'"]);
      assert.deepEqual([...canonicalMap.get("frame-ancestors")], ["'none'"]);
    });
    test("object-src is 'none'", () => assert.deepEqual([...canonicalMap.get("object-src")], ["'none'"]));

    console.log("\n[5] Static script/style hashes are present");
    test("script-src contains exactly one sha256 hash (the language-detection script)", () => {
      const hashes = [...canonicalMap.get("script-src")].filter((s) => s.startsWith("'sha256-"));
      assert.equal(hashes.length, 1);
      assert.equal(hashes[0], `'${csp.LANG_DETECT_SCRIPT_HASH}'`);
    });
    test("style-src contains exactly two sha256 hashes (the two distinct static inline style blocks)", () => {
      const hashes = [...canonicalMap.get("style-src")].filter((s) => s.startsWith("'sha256-"));
      assert.equal(hashes.length, 2);
      assert.ok(hashes.includes(`'${csp.SHAKE_KEYFRAMES_STYLE_HASH}'`));
      assert.ok(hashes.includes(`'${csp.PRACTICED_WORDS_CALLOUT_STYLE_HASH}'`));
    });

    console.log(`\n─────────────────────────────────────────`);
    console.log(`  ${passed} passed, ${failed} failed`);
    console.log(`─────────────────────────────────────────\n`);

    if (failed > 0) {
      process.exitCode = 1;
    } else {
      console.log("CSP policy parity tests passed");
    }
  } finally {
    compiled.cleanup();
  }
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
